$ErrorActionPreference = "Stop"

$frontend = "C:\Bruno\Proyectos\farmacia-inacap\frontend"
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path $frontend "backup-funcional-$stamp"
$temp = Join-Path $env:TEMP "farmagestion-funcional-$stamp"
$zip = Join-Path $temp "patch.zip"
$log = Join-Path $frontend "integracion_funcional.log"

$files = @(
  "src\\components\\ui\\ActionModal.tsx",
  "src\\lib\\actionHelpers.ts",
  "src\\components\\layout\\Topbar.tsx",
  "src\\pages\\ProductsPage.tsx",
  "src\\pages\\PatientsPage.tsx",
  "src\\pages\\DoctorsPage.tsx",
  "src\\pages\\UsersPage.tsx",
  "src\\pages\\SettingsPage.tsx",
  "src\\pages\\CashPage.tsx",
  "src\\pages\\SalesPage.tsx",
  "src\\pages\\InventoryPage.tsx",
  "src\\pages\\PurchasesPage.tsx",
  "src\\pages\\PrescriptionsPage.tsx",
  "src\\pages\\ControlledPage.tsx",
  "src\\pages\\AgreementsPage.tsx",
  "src\\pages\\PosPage.tsx",
  "src\\styles\\index.css"
)

function Restore-Backup {
  foreach ($rel in $files) {
    $src = Join-Path $backup $rel
    $dst = Join-Path $frontend $rel
    if (Test-Path $src) {
      New-Item -ItemType Directory -Force -Path (Split-Path $dst) | Out-Null
      Copy-Item $src $dst -Force
    }
  }
}

if (-not (Test-Path $frontend)) {
  Write-Host "No existe frontend: $frontend" -ForegroundColor Red
  Read-Host "ENTER para salir"
  exit 1
}

if (Test-Path $log) { Remove-Item $log -Force }
Start-Transcript -Path $log -Force | Out-Null

try {
  Write-Host "==> Preparando integración funcional completa..." -ForegroundColor Cyan

  New-Item -ItemType Directory -Force -Path $backup | Out-Null
  New-Item -ItemType Directory -Force -Path $temp | Out-Null

  foreach ($rel in $files) {
    $src = Join-Path $frontend $rel
    if (Test-Path $src) {
      $dst = Join-Path $backup $rel
      New-Item -ItemType Directory -Force -Path (Split-Path $dst) | Out-Null
      Copy-Item $src $dst -Force
    }
  }

  $payload = @'

'@

  [System.IO.File]::WriteAllBytes(
    $zip,
    [Convert]::FromBase64String(($payload -replace "\s",""))
  )

  Expand-Archive -Path $zip -DestinationPath $temp -Force

  foreach ($rel in $files) {
    $src = Join-Path $temp $rel
    $dst = Join-Path $frontend $rel

    if (-not (Test-Path $src)) {
      throw "Falta archivo en el parche: $rel"
    }

    New-Item -ItemType Directory -Force -Path (Split-Path $dst) | Out-Null
    Copy-Item $src $dst -Force
  }

  Set-Location $frontend

  Write-Host "==> Ejecutando build..." -ForegroundColor Cyan
  npm run build

  if ($LASTEXITCODE -ne 0) {
    throw "npm run build terminó con código $LASTEXITCODE"
  }

  Write-Host ""
  Write-Host "========================================================" -ForegroundColor Green
  Write-Host " INTEGRACION FUNCIONAL APLICADA CORRECTAMENTE" -ForegroundColor Green
  Write-Host "========================================================" -ForegroundColor Green
  Write-Host ""
  Write-Host "Backup: $backup" -ForegroundColor DarkGray
  Write-Host "Log: $log" -ForegroundColor DarkGray
  Write-Host "Ahora ejecuta: npm run dev" -ForegroundColor Yellow
}
catch {
  Write-Host ""
  Write-Host "========================================================" -ForegroundColor Red
  Write-Host " ERROR EN LA INTEGRACION FUNCIONAL" -ForegroundColor Red
  Write-Host "========================================================" -ForegroundColor Red
  Write-Host $_.Exception.Message -ForegroundColor Yellow
  Write-Host ""
  Write-Host "Restaurando backup..." -ForegroundColor Yellow
  Restore-Backup
  Write-Host "Restauración completada." -ForegroundColor Yellow
  Write-Host "Log: $log" -ForegroundColor Cyan
}
try { Stop-Transcript | Out-Null } catch {}

if (Test-Path $temp) {
  Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue
}

Read-Host "Presiona ENTER para finalizar"
